    boxes = {}
    for color in (7, 9):
        cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
        boxes[color] = (min(r for r,c in cells), max(r for r,c in cells), min(c for r,c in cells), max(c for r,c in cells))
    a = boxes[7]
    b = boxes[9]
    for r in range(len(grid)):
