                out[r][c] = 6
            elif grid[r][c] == 9:
                out[r][c] = 7
            elif grid[r][c] == 6:
                vertical = a[2] == b[2] and a[3] == b[3] and b[2] <= c <= b[3] and min(a[0], b[0]) < r < max(a[1], b[1])
                horizontal = a[0] == b[0] and a[1] == b[1] and b[0] <= r <= b[1] and min(a[2], b[2]) < c < max(a[3], b[3])
                if vertical or horizontal:
                    # The red bridge only occupies dashed guide lines.

